// Calories and macros for recipes, calculated from USDA data instead of
// guessed. Each ingredient name maps to a USDA SR Legacy food (per-100 g
// nutrition) plus gram weights of household portions (1 cup, 1 clove, one
// medium piece...), so "1 1/2 cups" or "2 cloves" can be turned into grams.
//
// data/ingredient-nutrition.json is generated by scripts/recipe-data/ (USDA
// SR Legacy + TheMealDB's ingredient list, matched with the AI model and
// checked by hand); see the README there.
import ingredientData from '../data/ingredient-nutrition.json';

export interface Per100 {
  kcal: number;
  protein: number;
  carbs: number;
  fat: number;
  fiber: number;
}

export interface IngredientInfo {
  name: string;
  fdc: number | null; // USDA FoodData Central id
  usda: string | null; // USDA description, e.g. "Onions, raw"
  category?: string | null; // the app's food category (vegetables, dairy...)
  per100: Per100 | null;
  // Grams of one portion: cup, tbsp, tsp, piece, clove, slice, stick, can...
  g: Partial<Record<string, number>>;
}

const INGREDIENTS = ingredientData as Record<string, IngredientInfo>;

function singular(word: string): string {
  if (word.endsWith('ies') && word.length > 4) return word.slice(0, -3) + 'y';
  if (word.endsWith('oes') && word.length > 4) return word.slice(0, -2);
  if (word.endsWith('s') && !word.endsWith('ss') && word.length > 3) return word.slice(0, -1);
  return word;
}

const normalise = (name: string) => name.trim().toLowerCase().replace(/\s+/g, ' ');
const SINGULAR_INDEX = new Map(
  Object.entries(INGREDIENTS).map(([key, info]) => [key.split(' ').map(singular).join(' '), info])
);

/** The ingredient's USDA data, or null if it isn't in the table. */
export function findIngredient(name: string): IngredientInfo | null {
  const key = normalise(name);
  return INGREDIENTS[key] ?? SINGULAR_INDEX.get(key.split(' ').map(singular).join(' ')) ?? null;
}

// ── Measures ─────────────────────────────────────────────────────────────

const FRACTIONS: Record<string, string> = { '½': ' 1/2', '¼': ' 1/4', '¾': ' 3/4', '⅓': ' 1/3', '⅔': ' 2/3', '⅛': ' 1/8' };

// Order matters: longer spellings first
const UNITS: [string, RegExp][] = [
  ['kg', /^(kg|kgs|kilos?|kilograms?)\b/],
  ['g', /^(g|gr|grams?|grammes?)\b/],
  ['ml', /^(ml|mls|millilit(re|er)s?)\b/],
  ['cl', /^cl\b/],
  ['dl', /^dl\b/],
  ['l', /^(l|ltr|lit(re|er)s?)\b/],
  ['oz', /^(oz|ozs|ounces?)\b/],
  ['lb', /^(lbs?|pounds?)\b/],
  ['cup', /^(cups?|c)\b/],
  ['tbsp', /^(tbsp|tbsps|tbs|tblsp|tbls|tbl|tablespoons?|tablespoonfuls?)\b/],
  ['tsp', /^(tsp|tsps|teaspoons?|teaspoonfuls?)\b/],
  ['pinch', /^pinch(es)?\b/],
  ['dash', /^dash(es)?\b/],
  ['splash', /^splash(es)?\b/],
  ['drizzle', /^drizzle\b/],
  ['knob', /^knobs?\b/],
  ['handful', /^handfuls?\b/],
  ['bunch', /^bunch(es)?\b/],
  ['sprig', /^sprigs?\b/],
  ['clove', /^cloves?\b/],
  ['slice', /^slices?\b/],
  ['stick', /^sticks?\b/],
  ['can', /^(cans?|tins?)\b/],
  ['pack', /^(packets?|packs?|packages?|bags?|pots?|jars?|cartons?|tubs?|bottles?)\b/],
  ['head', /^heads?\b/],
  ['bulb', /^bulbs?\b/],
  ['leaf', /^lea(f|ves)\b/],
  ['stalk', /^stalks?\b/],
];
const SIZES: Record<string, number> = { large: 1.25, big: 1.25, medium: 1, small: 0.75 };

// No amount: seasoning to taste, a garnish or a side served with the dish
const NEGLIGIBLE = /\b(to taste|garnish|to serve|serving|dusting|sprinkl|topping|as required|as needed|optional|decorat|to glaze)/;
const FOR_COOKING = /\b(for frying|for brushing|for greasing|for the pan|for cooking|drizzle)/;

function parseAmount(text: string): { value: number | null; rest: string } {
  // "1/2", "1 1/2", "1.5", "2-3" / "2 to 3" (-> 2.5)
  const m = /^(\d+)\/(\d+)|^(\d+(?:\.\d+)?)(?:\s+(\d+)\/(\d+))?(?:\s*(?:-|–|to)\s*(\d+(?:\.\d+)?))?/.exec(text);
  if (!m) return { value: null, rest: text };
  let value: number;
  if (m[1]) value = Number(m[1]) / Number(m[2]);
  else {
    value = Number(m[3]) + (m[4] ? Number(m[4]) / Number(m[5]) : 0);
    if (m[6]) value = (value + Number(m[6])) / 2;
  }
  return { value: value > 0 ? value : null, rest: text.slice(m[0].length).trim() };
}

export interface ParsedMeasure {
  amount: number | null;
  unit: string | null; // one of UNITS' keys, a size word, or null = pieces
}

export function parseMeasure(measure: string | null | undefined): ParsedMeasure {
  let text = (measure || '').toLowerCase();
  for (const [f, v] of Object.entries(FRACTIONS)) text = text.split(f).join(v);
  // "250g/9oz", "1 cup (240ml)": the first measure is enough. A slash after
  // a letter starts the second measure; one between digits is a fraction.
  text = text
    .split('(')[0]
    .replace(/([a-z])\s*\/.*$/, '$1')
    .replace(/(\d)\s*\/\s*(\d)/g, '$1/$2')
    .replace(/\s+/g, ' ')
    .trim();

  const { value, rest } = parseAmount(text);
  const words = rest.split(' ').filter(Boolean);
  // "250g" leaves "g"; "1 heaped tbsp" -> skip "heaped"; "2 large handfuls" -> handful
  for (let i = 0; i < Math.min(words.length, 3); i++) {
    const candidate = words.slice(i).join(' ');
    for (const [unit, re] of UNITS) if (re.test(candidate)) return { amount: value, unit };
  }
  const size = words.find((w) => w in SIZES);
  return { amount: value, unit: size ?? null };
}

/**
 * Grams of an ingredient for a recipe measure, or null when it can't be told
 * (e.g. "1 Flour"). Seasonings "to taste" and garnishes count as 0 g.
 */
export function measureToGrams(measure: string | null | undefined, info: IngredientInfo | null): number | null {
  const raw = (measure || '').toLowerCase().trim();
  const g = info?.g ?? {};
  const piece = g.piece;
  const cup = g.cup ?? 240;
  const tbsp = g.tbsp ?? cup / 16;
  const tsp = g.tsp ?? tbsp / 3;

  // "Juice of 1" lemon is about a third of the fruit's weight, "zest of 1" ~2 g
  const juice = /juice (?:of|from) (\d+|one|two|half|a|an)?/.exec(raw);
  const zest = /zest (?:of|from) (\d+|one|two|half|a|an)?/.exec(raw);
  if (juice || zest) {
    const word = (juice || zest)![1] || '1';
    const n = { one: 1, a: 1, an: 1, two: 2, half: 0.5 }[word] ?? (Number(word) || 1);
    return juice ? n * (piece ?? 85) * 0.35 : n * 2;
  }

  const { amount, unit } = parseMeasure(raw);
  const qty = amount ?? 1;
  let grams: number | null;
  switch (unit) {
    case 'g': grams = qty; break;
    case 'kg': grams = qty * 1000; break;
    case 'oz': grams = qty * 28.35; break;
    case 'lb': grams = qty * 453.6; break;
    case 'ml': grams = (qty * cup) / 240; break;
    case 'cl': grams = (qty * 10 * cup) / 240; break;
    case 'dl': grams = (qty * 100 * cup) / 240; break;
    case 'l': grams = (qty * 1000 * cup) / 240; break;
    case 'cup': grams = qty * cup; break;
    case 'tbsp': grams = qty * tbsp; break;
    case 'tsp': grams = qty * tsp; break;
    case 'pinch': grams = qty * 0.35; break;
    case 'dash': grams = qty * 0.6; break;
    case 'splash': case 'drizzle': grams = qty * tbsp; break;
    case 'knob': grams = qty * 15; break;
    case 'handful': grams = qty * 30; break;
    case 'bunch': grams = qty * (g.bunch ?? 50); break;
    case 'sprig': grams = qty * (g.sprig ?? 1); break;
    case 'leaf': grams = qty * (g.leaf ?? 0.5); break;
    case 'clove': grams = qty * (g.clove ?? 3); break;
    case 'slice': grams = qty * (g.slice ?? 30); break;
    case 'stick': grams = qty * (g.stick ?? piece ?? 113); break;
    case 'stalk': grams = qty * (g.stalk ?? piece ?? 40); break;
    case 'can': grams = qty * (g.can ?? 400); break;
    case 'pack': grams = qty * (piece ?? 200); break;
    case 'head': case 'bulb': grams = qty * (g.head ?? piece ?? 300); break;
    case 'large': case 'big': case 'medium': case 'small':
      grams = piece ? qty * piece * SIZES[unit] : null; break;
    default:
      if (amount != null) grams = piece ? qty * piece : null;
      else if (FOR_COOKING.test(raw)) grams = tbsp;
      else if (NEGLIGIBLE.test(raw) || !raw) grams = raw ? 0 : piece ?? null;
      else grams = null;
  }
  return grams == null || !isFinite(grams) ? null : Math.min(Math.round(grams * 10) / 10, 5000);
}

/** The DB's unit_type for a measure, so lists show "2 tbsp", not "30 g" */
export function measureForDb(measure: string | null | undefined, grams: number | null): { quantity: number; unit: string } {
  const { amount, unit } = parseMeasure(measure);
  const qty = amount ?? 1;
  if (unit && ['g', 'kg', 'ml', 'l', 'cup', 'tbsp', 'tsp', 'slice'].includes(unit)) return { quantity: qty, unit };
  if (unit === 'oz' || unit === 'lb') return { quantity: grams ?? qty, unit: 'g' };
  if (unit === 'cl') return { quantity: qty * 10, unit: 'ml' };
  if (unit === 'dl') return { quantity: qty * 100, unit: 'ml' };
  return { quantity: qty, unit: 'piece' };
}

// ── Recipe totals ────────────────────────────────────────────────────────

export interface NutritionLine {
  name: string;
  grams: number | null;
  info: IngredientInfo | null;
}

export interface RecipeNutrition {
  calories: number;
  protein_g: number;
  carbs_g: number;
  fat_g: number;
  fiber_g: number;
  /** Ingredients left out of the totals: no USDA match or no usable amount */
  missing: string[];
}

const round1 = (n: number) => Math.round(n * 10) / 10;

export function recipeNutrition(lines: NutritionLine[], servings: number): RecipeNutrition {
  const total = { kcal: 0, protein: 0, carbs: 0, fat: 0, fiber: 0 };
  const missing: string[] = [];
  for (const line of lines) {
    if (line.grams == null || !line.info?.per100) {
      // 0 g (salt "to taste") without data costs nothing, so it isn't "missing"
      if (line.grams !== 0) missing.push(line.name);
      continue;
    }
    const k = line.grams / 100;
    for (const key of Object.keys(total) as (keyof Per100)[]) total[key] += (line.info.per100[key] ?? 0) * k;
  }
  const s = Math.max(1, servings || 1);
  return {
    calories: Math.round(total.kcal / s),
    protein_g: round1(total.protein / s),
    carbs_g: round1(total.carbs / s),
    fat_g: round1(total.fat / s),
    fiber_g: round1(total.fiber / s),
    missing,
  };
}
